import base64
import json

texto_base64 = ""
texto_base64 = texto_base64.strip()
texto_base64 += "=" * (-len(texto_base64) % 4)

json_texto = base64.b64decode(texto_base64).decode("utf-8")
dados = json.loads(json_texto)

licoes = dados["course"]["lessons"]

# Ordena pela posição, caso a lista não esteja perfeitamente ordenada
licoes_ordenadas = sorted(licoes, key=lambda x: x.get("position", 0))

estrutura_licoes = []

for i, licao in enumerate(licoes_ordenadas, start=1):
    estrutura_licoes.append({
        "numero_da_licao": i,
        "position_original": licao.get("position"),
        "titulo": licao.get("title"),
        "descricao": licao.get("description"),
        "quantidade_de_blocos": len(licao.get("items", [])),
        "ids_dos_blocos": [item.get("id") for item in licao.get("items", [])],
        "tipos_dos_blocos": [item.get("type") for item in licao.get("items", [])]
    })

with open("estrutura_licoes.json", "w", encoding="utf-8") as arquivo:
    json.dump(estrutura_licoes, arquivo, ensure_ascii=False, indent=2)

print("Arquivo gerado: estrutura_licoes.json")